    /// </summary>
    /// <example>
    /// <code>
    /// ```ts
    /// class Chat extends Agent {
    ///   onStart() {
    ///     console.log("chat started under:", this.parentPath);
    ///     // → [{ className: "Tenant", name: "acme" }, { className: "Inbox", name: "alice" }]
    ///   }
    /// }
    /// </code>
    /// <code>
    /// </code>
    /// </example>
