module Workflows =
    /// <summary>
    /// Type alias for WorkflowEvent in AgentWorkflow context.
    /// Identical to WorkflowEvent - provided for naming consistency with AgentWorkflowStep.
    /// </summary>
    [<Erase>]
    type AgentWorkflowEvent<'Params> = private AgentWorkflowEvent__ of obj

    /// <summary>
    /// Extended WorkflowStep with durable Agent communication methods.
    /// All added methods on this interface are durable - they're idempotent and won't
    /// repeat on workflow retry.
    /// </summary>
    type AgentWorkflowStep =
        /// <summary>
        /// Report successful completion to the Agent (durable).
        /// Triggers onWorkflowComplete() on the Agent.
        /// </summary>
        /// <param name="result">- Optional result data</param>
        abstract reportComplete<'T>: ?result: 'T -> JS.Promise<unit>
        /// <summary>
        /// Report an error to the Agent (durable).
        /// Triggers onWorkflowError() on the Agent.
        /// </summary>
        /// <param name="error">- Error or error message</param>
        abstract reportError: error: U2<string, exn> -> JS.Promise<unit>
        /// <summary>
        /// Send a custom event to the Agent (durable).
        /// Triggers onWorkflowEvent() on the Agent.
        /// </summary>
        /// <param name="event">- Custom event payload</param>
        abstract sendEvent<'T>: ``event``: 'T -> JS.Promise<unit>
        /// <summary>
        /// Update the Agent's state entirely (durable).
        /// This will replace the Agent's state and broadcast to all connected clients.
        /// </summary>
        /// <param name="state">- New state to set</param>
        abstract updateAgentState: state: obj -> JS.Promise<unit>
        /// <summary>
        /// Merge partial state into the Agent's existing state (durable).
        /// Performs a shallow merge and broadcasts to all connected clients.
        /// </summary>
        /// <param name="partialState">- Partial state to merge</param>
        abstract mergeAgentState: partialState: Record<string, obj> -> JS.Promise<unit>
        /// <summary>
        /// Reset the Agent's state to its initialState (durable).
        /// Broadcasts the reset state to all connected clients.
        /// </summary>
        abstract resetAgentState: unit -> JS.Promise<unit>
        abstract ``do``<'T>: name: string * callback: (obj -> JS.Promise<'T>) * ?rollbackOptions: obj -> JS.Promise<'T>
        abstract ``do``<'T>: name: string * config: Workflows.AgentWorkflowStep.Do.Config * callback: (obj -> JS.Promise<'T>) * ?rollbackOptions: obj -> JS.Promise<'T>
        abstract ``do``<'T>: name: string * config: Workflows.AgentWorkflowStep.Do.Config2 * callback: (obj -> JS.Promise<'T>) * ?rollbackOptions: obj -> JS.Promise<'T>
        abstract ``do``<'T>: name: string * config: obj * callback: (obj -> JS.Promise<'T>) * ?rollbackOptions: obj -> JS.Promise<'T>
        abstract sleep: Workflows.AgentWorkflowStep.Sleep with get, set
        abstract sleepUntil: Workflows.AgentWorkflowStep.SleepUntil with get, set
